function hsvBin(r,g,b){const mx=Math.max(r,g,b),mn=Math.min(r,g,b),v=mx/255,d=mx-mn,sat=mx?d/mx:0;if(v<.2)return 0;if(sat<.15)return v>.75?1:2;let h=d?(mx===r?((g-b)/d)%6:mx===g?(b-r)/d+2:(r-g)/d+4)*60:0;if(h<0)h+=360;return 3+Math.floor(h/30)%12*2+(v>.55?1:0)}
const normH=a=>{const t=a.reduce((x,y)=>x+y,0)||1;return a.map(x=>+(x/t).toFixed(3))};
function sigOf(id){const c={},a=Array(HB).fill(0);(SCN[id]||'').replace(/#[0-9a-fA-F]{6}/g,m=>{c[m]=(c[m]||0)+1});for(const k in c)a[hsvBin(parseInt(k.slice(1,3),16),parseInt(k.slice(3,5),16),parseInt(k.slice(5,7),16))]+=c[k];return normH(a)}
