function burn(c,t,o){const x=c.getContext('2d'),fs=Math.max(16,Math.round(c.width/24));x.save();x.font=`700 ${fs}px "Noto Sans Thai",sans-serif`;x.textAlign='center';x.textBaseline='middle';x.fillStyle=`rgba(255,255,255,${o})`;x.strokeStyle=`rgba(0,0,0,${o*.55})`;x.lineWidth=Math.max(1,fs/16);
const sx=x.measureText(t).width+fs*2,sy=fs*3.6,d=Math.hypot(c.width,c.height);x.translate(c.width/2,c.height/2);x.rotate(-Math.PI/6);
for(let r=0,yy=-d;yy<d;yy+=sy,r++)for(let xx=-d+(r%2)*sx/2;xx<d;xx+=sx){x.strokeText(t,xx,yy);x.fillText(t,xx,yy)}x.restore()}
function resize(file,max,cb,wm,sg){const r=new FileReader();r.onload=()=>{const i=new Image();i.onload=()=>{const k=Math.min(1,max/Math.max(i.width,i.height)),c=document.createElement('canvas');c.width=i.width*k;c.height=i.height*k;c.getContext('2d').drawImage(i,0,0,c.width,c.height);if(sg)sg.v=histOf(c);if(wm)burn(c,wm,db.wm.op);cb(c.toDataURL('image/jpeg',.82))};i.src=r.result};r.readAsDataURL(file)}
const rz=(f,m,wm,sg)=>new Promise(r=>resize(f,m,r,wm,sg));
const dimOf=f=>new Promise((res,rej)=>{const u=URL.createObjectURL(f),i=new Image();i.onload=()=>{res({w:i.naturalWidth,h:i.naturalHeight});URL.revokeObjectURL(u)};i.onerror=rej;i.src=u});
let _wk='',_wv='';
function wmBg(){const t=db.wm.text,o=db.wm.op,k=t+o;if(k!==_wk){const v=`<svg xmlns='http://www.w3.org/2000/svg' width='240' height='150'><text x='120' y='75' transform='rotate(-28 120 75)' text-anchor='middle' font-family='sans-serif' font-size='20' font-weight='700' fill='white' fill-opacity='${o}' stroke='black' stroke-opacity='${o*.5}' stroke-width='.7'>${esc(t)}</text></svg>`;_wv='url('+encodeURIComponent(v).replace(/'/g,'%27').replace(/\(/g,'%28').replace(/\)/g,'%29').replace(/^/,'data:image/svg+xml,')+')';_wk=k}return _wv}
const idb=()=>new Promise((res,rej)=>{const r=indexedDB.open('artcorner',1);r.onupgradeneeded=()=>r.result.createObjectStore('hi');r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)});
const hiPut=async(k,b)=>{const d=await idb();return new Promise((res,rej)=>{const t=d.transaction('hi','readwrite');t.objectStore('hi').put(b,k);t.oncomplete=res;t.onerror=()=>rej(t.error)})};
const hiGet=async k=>{const d=await idb();return new Promise((res,rej)=>{const q=d.transaction('hi').objectStore('hi').get(k);q.onsuccess=()=>res(q.result);q.onerror=()=>rej(q.error)})};
const hiDel=async k=>{const d=await idb();return new Promise(res=>{const t=d.transaction('hi','readwrite');t.objectStore('hi').delete(k);t.oncomplete=res;t.onerror=res})};
const svgPng=w=>new Promise((res,rej)=>{const a=w.digital.w,b=w.digital.h,v=SCN[w.svg].replace(/ style="[^"]*"/,'').replace('<svg ',`<svg xmlns="http://www.w3.org/2000/svg" width="${a}" height="${b}" `),i=new Image();i.onload=()=>{const c=document.createElement('canvas');c.width=a;c.height=b;c.getContext('2d').drawImage(i,0,0,a,b);c.toBlob(x=>x?res(x):rej(),'image/png')};i.onerror=rej;i.src=URL.createObjectURL(new Blob([v],{type:'image/svg+xml'}))});
async function dlFile(id){const w=W(id);if(!w?.digital)return;const ok=isMgr()||(isA()&&w.artist===me().artist)||db.orders.some(o=>o.uid===db.session&&!o.cancelled&&o.status>=1&&(o.dl||[]).includes(id));
if(!ok)return toast('ยังไม่มีสิทธิ์ดาวน์โหลด — ต้องชำระเงินและรอการยืนยันก่อน');
try{let b;if(w.digital.file){b=await hiGet(id);if(!b)return toast('ไม่พบไฟล์ในเบราว์เซอร์นี้ (เดโม: ไฟล์เก็บไว้ในเครื่องที่อัปโหลด)')}else b=await svgPng(w);
const a=document.createElement('a');a.href=URL.createObjectURL(b);a.download=`${w.title}-${w.digital.w}x${w.digital.h}.${w.digital.file?(w.digital.fmt||'jpg').toLowerCase().replace('jpeg','jpg'):'png'}`;document.body.appendChild(a);a.click();a.remove();toast('เริ่มดาวน์โหลดแล้ว')}catch(e){toast('ดาวน์โหลดไม่สำเร็จ')}}
const cartTotal=()=>db.cart.map(W).filter(w=>w&&w.status==='available'&&!isMine(w)).reduce((a,w)=>a+w.price,0)+db.cartD.map(W).filter(w=>w&&w.digital&&!isMine(w)).reduce((a,w)=>a+w.digital.price,0);
function addDigital(id){const w0=W(id);if(w0&&isMine(w0))return toast('ซื้อผลงานของตัวเองไม่ได้');if(!db.cartD.includes(id))db.cartD.push(id);save();toast('เพิ่มไฟล์ดิจิทัลลงตะกร้าแล้ว');go()}
const WMBOX=()=>`<div class="box" style="max-width:420px"><label>ข้อความลายน้ำ (ประทับบนรูปตัวอย่างอัตโนมัติ)</label><input id="wt" value="${esc(db.wm.text)}"><label>ความเข้มลายน้ำ (10–60%)</label><input id="wo" type="number" value="${Math.round(db.wm.op*100)}"><div class="err" id="werr"></div><br><button class="btn" onclick="saveWM()">บันทึก</button><p class="mu">มีผลกับรูปที่อัปโหลดหลังจากนี้ รูปเดิมที่อัปโหลดไว้แล้วต้องอัปโหลดใหม่</p></div>`;
function saveWM(){const t=val('wt'),o=+val('wo');if(!chk('werr',[[t.length<2||t.length>30,'ข้อความลายน้ำ 2–30 ตัวอักษร'],[!Number.isInteger(o)||o<10||o>60,'ความเข้มเป็นจำนวนเต็ม 10–60']]))return;log('แก้ไข','ตั้งค่า','ลายน้ำ',db.wm.text+' '+Math.round(db.wm.op*100)+'% → '+t+' '+o+'%');db.wm={text:t,op:o/100};save();toast('บันทึกแล้ว');go()}
function pp(id,amt){const t=(k,v)=>k+String(v.length).padStart(2,'0')+v;id=id.replace(/\D/g,'');const acc=id.length>=13?t('02',id):t('01','0066'+id.slice(1));
let s=t('00','01')+t('01','12')+t('29',t('00','A000000677010111')+acc)+t('53','764')+t('54',amt.toFixed(2))+t('58','TH')+'6304',c=0xFFFF;
for(const ch of s){c^=ch.charCodeAt(0)<<8;for(let i=0;i<8;i++)c=c&0x8000?((c<<1)^0x1021)&0xFFFF:(c<<1)&0xFFFF}return s+c.toString(16).toUpperCase().padStart(4,'0')}
