const gO=id=>db.orders.find(o=>o.id===id),ost=o=>o.cancelled?'ยกเลิก':ST[o.status];
function setSt(id,s){if(!isMgr())return;const o=gO(id),b=o.status;o.status=s;if(o.com&&s===1){const c=gC(o.com);if(c&&!c.end&&c.status===2)c.status=3}log('เปลี่ยนสถานะ','คำสั่งซื้อ',id,ST[b]+' → '+ST[s]);save();go()}
function ship(id){const t=prompt('เลขพัสดุ');if(t===null)return;if(!/^[A-Za-z0-9-]{6,30}$/.test(t.trim()))return toast('เลขพัสดุต้องเป็นตัวอักษร/ตัวเลข 6–30 ตัว');gO(id).tracking=t.trim();setSt(id,2)}
