function delUser(id){const u=db.users.find(x=>x.id===id);
if(u.id===db.session)return toast('ลบบัญชีตัวเองไม่ได้');if(u.role==='admin'&&db.users.filter(x=>x.role==='admin').length<2)return toast('ต้องมีแอดมินอย่างน้อย 1 คน');
if(db.orders.some(o=>o.uid===id)||(u.artist&&db.works.some(w=>w.artist===u.artist))||db.coms.some(c=>c.uid===id||(u.artist&&c.artist===u.artist)))return toast('ลบไม่ได้: ผู้ใช้มีคำสั่งซื้อหรือผลงานอยู่');
if(!confirm('ลบผู้ใช้ '+u.email+' ?'))return;db.users=db.users.filter(x=>x.id!==id);db.apps=db.apps.filter(a=>a.uid!==id);db.likes=db.likes.filter(l=>l.u!==id);db.follows=db.follows.filter(f=>f.u!==id);db.reviews=db.reviews.filter(r=>r.u!==id);log('ลบ','ผู้ใช้',id,u.email);save();go()}
