if(!chk('aerr',[[n.length<2,'ชื่ออย่างน้อย 2 ตัวอักษร'],[!EM.test(e),'รูปแบบอีเมลไม่ถูกต้อง'],[!REMOTE&&db.users.some(u=>u.email===e),'อีเมลนี้ถูกใช้แล้ว'],[w.length<6,'รหัสผ่านอย่างน้อย 6 ตัวอักษร']]))return;
