// ===== โหมดออนไลน์: ซิงก์ข้อมูลกับเซิร์ฟเวอร์ (Vercel Function + Upstash Redis) =====
const LK='artcorner_local',KEYS={works:x=>x.id,artists:x=>x.id,users:x=>x.id,orders:x=>x.id,coms:x=>x.id,reviews:x=>x.id,apps:x=>x.id,likes:x=>x.u+'|'+x.w,follows:x=>x.u+'|'+x.a,logs:x=>x.i};
async function api(a,b={}){try{const r=await fetch('/api/app',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({a,token:TOK,...b}),signal:(typeof AbortSignal!=='undefined'&&AbortSignal.timeout)?AbortSignal.timeout(a==='ping'?6000:20000):undefined});const j=await r.json().catch(()=>null);return j||{ok:false,err:'เซิร์ฟเวอร์ไม่ตอบกลับ',net:1}}catch(e){return{ok:false,err:'เชื่อมต่อเซิร์ฟเวอร์ไม่ได้',net:1}}}
const persistLocal=()=>{try{localStorage.setItem(LK,JSON.stringify({tok:TOK,session:db.session,cart:db.cart,cartD:db.cartD}))}catch(e){}};
const mapOf=(c,arr)=>{const m={};(arr||[]).forEach(x=>{const k=KEYS[c](x);if(k)m[k]=JSON.stringify(x)});return m};
function snapshot(){BASE={};Object.keys(KEYS).forEach(c=>{BASE[c]=mapOf(c,db[c])});BASE.settings={cats:JSON.stringify(db.cats),wm:JSON.stringify(db.wm),qr:JSON.stringify(db.qr||'')}}
function collect(){const ops=[];Object.keys(KEYS).forEach(c=>{const cur=mapOf(c,db[c]),b=BASE[c]||{};for(const k in cur)if(b[k]!==cur[k])ops.push({c,id:k,v:JSON.parse(cur[k])});if(c!=='logs')for(const k in b)if(!(k in cur))ops.push({c,id:k,v:null})});
const st={cats:db.cats,wm:db.wm,qr:db.qr||''};for(const k in st)if(BASE.settings[k]!==JSON.stringify(st[k]))ops.push({c:'settings',id:k,v:st[k]});return ops}
async function push(){const ops=collect();if(!ops.length)return;const r=await api('sync',{ops});
if(r.ok){ops.forEach(o=>{if(o.c==='settings')BASE.settings[o.id]=JSON.stringify(o.v);else if(o.v===null)delete BASE[o.c][o.id];else BASE[o.c][o.id]=JSON.stringify(o.v)});V=null}
else if(r.net)toast(r.err);else{toast(r.err||'บันทึกไม่สำเร็จ');V=null;await pull(true,true)}}
const FORMS=/^(hire|upload|edit|apply|profile|login|register)$/;
function rerender(){const a=document.activeElement,p=location.hash.slice(2).split('/')[0];if(a&&/INPUT|TEXTAREA|SELECT/.test(a.tagName))return;FORMS.test(p)?nav():go()}
async function pull(force,discard){const r=await api('state',{since:force?null:V});if(!r.ok||r.same)return;if(!discard&&collect().length)return;
V=r.v;if(!r.auth&&TOK){TOK='';db.session=null;persistLocal()}
const sig=JSON.stringify(r.data)+(r.me?r.me.id:'');if(sig===LAST&&!discard)return;LAST=sig;
Object.keys(KEYS).forEach(c=>{db[c]=r.data[c]||[]});db.cats=r.data.settings.cats;db.wm=r.data.settings.wm;db.qr=r.data.settings.qr||'';if(r.me)db.session=r.me.id;snapshot();rerender()}
const flush=async()=>{let q;do{q=Q;await q}while(q!==Q)};
function poll(){if(REMOTE&&document.visibilityState!=='hidden')Q=Q.then(async()=>{await push();await pull()}).catch(()=>{})}
async function boot(){const r=await api('ping');REMOTE=!!(r.ok&&r.remote);if(!REMOTE){go();return}
let L={};try{L=JSON.parse(localStorage.getItem(LK)||'{}')}catch(e){}
TOK=L.tok||'';db={session:L.session||null,cart:L.cart||[],cartD:L.cartD||[],wish:[],cats:[...CATS],wm:{text:'ArtCorner',op:.35},qr:''};Object.keys(KEYS).forEach(c=>{db[c]=[]});snapshot();
await pull(true,true);go();setInterval(poll,15000);if(document.addEventListener)document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')poll()})}
function importSeed(){if(!confirm('นำเข้าศิลปินและผลงานตัวอย่าง 18 ชิ้น? (ไม่รวมบัญชีผู้ใช้)'))return;const s=seed();s.artists.forEach(a=>{if(!db.artists.some(x=>x.id===a.id))db.artists.push(a)});s.works.forEach(w=>{if(!db.works.some(x=>x.id===w.id))db.works.push(w)});log('นำเข้า','ข้อมูลตัวอย่าง','-','ผลงาน 18 ชิ้น');save();toast('นำเข้าแล้ว');go()}
const isMine=w=>!!(me()&&me().artist&&w.artist===me().artist);
